"""Weekly timesheet rows, one line of text per worker."""

from typing import Dict, Iterable, List, Tuple
from hourglass.models import Shift

def _totals(shifts: Iterable[Shift]) -> Dict[str, Tuple]:
    counts = {}
    for shift in shifts:
        if not shift.worker.strip():
            raise ValueError("shift has a blank worker")
        count, mins = counts.get(shift.worker, (0, 0))
        total = mins + shift.span.minutes
        counts[shift.worker] = (count + 1, total)
    return counts

def _busiest(entry: Tuple) -> Tuple:
    name, (_count, mins) = entry
    return (-mins, name)

def _row(name: str, count: int, mins: int) -> str:
    word = "shift" if count == 1 else "shifts"
    hours = f"{mins / 60:.1f}"
    return f"{name}: {count} {word}, {hours} hours"

# ---
def timesheet_rows(shifts: Iterable[Shift]) -> List[str]:
    """One line per worker, most scheduled hours first.

    Raises ValueError for no shifts or a blank worker name.
    """
    totals = _totals(shifts)
    if not totals:
        raise ValueError("no shifts given")
    ranked = sorted(totals.items(), key=_busiest)
    return [_row(name, *pair) for name, pair in ranked]

