import unittest

from hourglass.timesheet import timesheet_rows
from hourglass.models import Shift, Span

def make_shift(worker, start, end, day="mon"):
    return Shift(worker, day, Span(start * 60, end * 60))

class TimesheetRowsTests(unittest.TestCase):
    def test_counts_and_hours(self):
        rows = timesheet_rows(
            [
                make_shift("Brisa", 9, 17),
                make_shift("Brisa", 9, 13, "tue"),
            ]
        )
        self.assertEqual(
            rows, ["Brisa: 2 shifts, 12.0 hours"]
        )

    def test_singular_shift(self):
        rows = timesheet_rows([make_shift("Odell", 9, 12)])
        self.assertEqual(
            rows, ["Odell: 1 shift, 3.0 hours"]
        )

    def test_busiest_first(self):
        rows = timesheet_rows(
            [
                make_shift("Odell", 9, 12),
                make_shift("Brisa", 9, 17),
                make_shift("Quill", 9, 14),
            ]
        )
        names = [line.split(":")[0] for line in rows]
        self.assertEqual(names, ["Brisa", "Quill", "Odell"])

    def test_ties_sorted_by_name(self):
        rows = timesheet_rows(
            [
                make_shift("Quill", 9, 12),
                make_shift("Odell", 9, 12),
            ]
        )
        self.assertTrue(rows[0].startswith("Odell"))

    def test_one_decimal_place(self):
        shift = Shift("Odell", "mon", Span(540, 620))
        self.assertEqual(
            timesheet_rows([shift]),
            ["Odell: 1 shift, 1.3 hours"],
        )

    def test_empty_list(self):
        with self.assertRaises(ValueError):
            timesheet_rows([])

    def test_blank_worker(self):
        with self.assertRaises(ValueError):
            timesheet_rows([make_shift("  ", 9, 12)])
